/* prog26_wildcard_match.c
 * Reimplementation of the original binary's behaviour.
 *   - prints "USAGE"   if the command line is wrong or strings are >64 chars
 *   - prints "MATCH"   if pattern matches text (wildcards ? and *)
 *   - prints "NO_MATCH" otherwise
 *
 * The algorithm is a classic DP solution for wildcard matching.
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 64

int main(int argc, char *argv[])
{
    /* -----------------------------------------------------------------
       Argument validation – exactly two strings, each ≤ 64 characters.
       ----------------------------------------------------------------- */
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);

    if (plen > MAXLEN || tlen > MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* -----------------------------------------------------------------
       DP table: dp[i][j] == true  ⇔  pattern[0..i-1] matches text[0..j-1]
       Table size is (plen+1) × (tlen+1) ≤ 65 × 65.
       ----------------------------------------------------------------- */
    bool dp[MAXLEN + 1][MAXLEN + 1] = { false };

    dp[0][0] = true;                     /* empty pattern matches empty text */

    /* first column – pattern against empty text */
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];     /* * can match empty */
        else
            dp[i][0] = false;
    }

    /* fill the rest of the table */
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*')
                dp[i][j] = dp[i - 1][j]      /* * matches empty */
                        || dp[i][j - 1];    /* * consumes one character */
            else if (pc == '?')
                dp[i][j] = dp[i - 1][j - 1]; /* ? matches exactly one */
            else
                dp[i][j] = dp[i - 1][j - 1] && (pc == tc);
        }
    }

    /* -----------------------------------------------------------------
       Result – the cell dp[plen][tlen] tells us whether the whole pattern
       matches the whole text.
       ----------------------------------------------------------------- */
    if (dp[plen][tlen])
        puts("MATCH");
    else
        puts("NO_MATCH");

    return 0;
}
